// C unions contain a u64 value overlaid with endian-dependent bit-fields.
// Accessors retain the exact low-level representation while avoiding a Rust
// compiler-dependent bit-field layout.
macro_rules! csr_union { ($($name:ident),* $(,)?) => { $(#[repr(C)] #[derive(Copy,Clone)] pub union $name { pub value: u64 } )* }; }
